{
  "claims": [
    {
      "claim": "Human oral bioavailability values for related adenine nucleosides are at or above 20% (acyclovir ~20%; didanosine 22-28% and 38% fasting; fludarabine monophosphate 70%). However, acyclovir and didanosine lack the phosphonic acid moiety, and fludarabine monophosphate is a hydrolyzable phosphate prodrug rather than a stable phosphonate, so these results do not directly transfer to the query's ionized phosphonate.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 1", "Molecule 3", "Molecule 5", "Molecule 6"],
      "record_ids": ["Record 1-1", "Record 3-1", "Record 3-2", "Record 5-1", "Record 6-1"]
    },
    {
      "claim": "Affirmative low-bioavailability measurements for charged adenine-containing molecules in humans (ATP 3.2-14.9% by uric-acid surrogate; S-adenosylmethionine 0.58-2.6% absolute in most studies) support a fail prediction for a stable, charged phosphonate such as the query. These analogs are not highly transferable because of triphosphate/sulfonium groups and formulation issues, but no supplied high-F record involves a stable phosphonic acid.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 2", "Molecule 8"],
      "record_ids": ["Record 2-1", "Record 2-2", "Record 8-1", "Record 8-2", "Record 8-4", "Record 8-6", "Record 8-7", "Record 8-8", "Record 8-9", "Record 8-10"]
    }
  ],
  "final_prediction": "fail"
}
